//#region lib/editors/classic-editor.ts
var BlazorClassicEditor = class extends ClassicEditor {
	static async create(sourceElementOrDataOrConfig, config, reference) {
		config = configFactory(config);
		const editor = await super.create(sourceElementOrDataOrConfig, config);
		const wordCount = editor.plugins.get("WordCount");
		const wordCountElement = editor.ui.view.editable.element?.closest(".editor-container_classic-editor")?.querySelector(".editor_container__word-count");
		if (wordCountElement) wordCountElement.appendChild(wordCount.wordCountContainer);
		if (reference) editor.model.document.on("change:data", async () => {
			await reference.invokeMethodAsync("EditorValueChanged", editor.getData());
		});
		return editor;
	}
};
//#endregion
//#region lib/editors/decoupled-editor.ts
var BlazorDecoupledEditor = class extends DecoupledEditor {
	static async create(sourceElementOrDataOrConfig, config, reference) {
		config = configFactory(config);
		const editor = await super.create(sourceElementOrDataOrConfig, config);
		const containerElement = editor.ui.view.editable.element?.closest(".editor-container_document-editor");
		const toolbarElement = containerElement?.querySelector(".editor-container__toolbar");
		if (toolbarElement && editor.ui.view.toolbar.element) toolbarElement.appendChild(editor.ui.view.toolbar.element);
		const menuBarElement = containerElement?.querySelector(".editor-container__menu-bar");
		if (menuBarElement && editor.ui.view.menuBarView.element) menuBarElement.appendChild(editor.ui.view.menuBarView.element);
		if (reference) editor.model.document.on("change:data", async () => {
			await reference.invokeMethodAsync("EditorValueChanged", editor.getData());
		});
		return editor;
	}
};
//#endregion
